const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  return ['true', '1', 'yes', 'on'].includes(text(value).toLowerCase());
};

const toNullableBoolean = (value) => {
  if (
    value === null ||
    value === undefined ||
    text(value) === ''
  ) {
    return null;
  }

  if (typeof value === 'boolean') return value;

  const normalized = text(value).toLowerCase();

  if (['true', '1', 'yes', 'on', 'بله', 'بلی', 'آره', 'نعم'].includes(normalized)) {
    return true;
  }

  if (['false', '0', 'no', 'off', 'خیر', 'نه', 'لا'].includes(normalized)) {
    return false;
  }

  return 'invalid';
};

const clinic_name = text(input.clinic_name);
const mobile = text(input.mobile);
const appointment_id = Number(input.appointment_id ?? 0);
const request_goal = text(input.request_goal || 'doctor_question').toLowerCase();
const symptom_category = text(input.symptom_category || 'general').toLowerCase();
const chief_complaint = text(input.chief_complaint);
const duration_text = text(input.duration_text);

const severityRaw = Number(input.severity);
const severity =
  Number.isInteger(severityRaw) && severityRaw >= 0
    ? severityRaw
    : null;

const age_group = text(input.age_group || 'unknown').toLowerCase();

const nullableBooleanFields = [
  'pregnancy_possible',
  'is_worsening',
  'difficulty_breathing',
  'chest_pain',
  'loss_of_consciousness',
  'seizure',
  'severe_bleeding',
  'possible_overdose',
  'pregnancy_emergency_concern',
  'self_harm_or_violence',
];

const nullableBooleans = {};
const errors = [];

for (const field of nullableBooleanFields) {
  const value = toNullableBoolean(input[field]);

  if (value === 'invalid') {
    errors.push({
      field,
      message: `${field} باید true، false یا خالی باشد.`,
    });
  } else {
    nullableBooleans[field] = value;
  }
}

const chronic_conditions = text(input.chronic_conditions);
const current_medications = text(input.current_medications);
const source_channel = text(input.source_channel || 'web').toLowerCase();

const consent_to_contact = toBoolean(input.consent_to_contact);
const consent_to_store_health_information =
  toBoolean(input.consent_to_store_health_information);
const disclaimer_acknowledged =
  toBoolean(input.disclaimer_acknowledged);
const confirm_submission = toBoolean(input.confirm_submission);

const goals = [
  'service_selection',
  'urgency_guidance',
  'appointment_guidance',
  'pre_visit_question',
  'doctor_question',
  'other',
];

const ageGroups = [
  'child',
  'adolescent',
  'adult',
  'older_adult',
  'unknown',
];

const channels = [
  'web',
  'whatsapp',
  'sms',
  'phone',
  'telegram',
  'manual',
  'api',
];

if (!clinic_name) {
  errors.push({
    field: 'clinic_name',
    message: 'نام کلینیک الزامی است.',
  });
}

if (!/^\+?[0-9]{8,15}$/.test(mobile)) {
  errors.push({
    field: 'mobile',
    message: 'شماره موبایل معتبر نیست.',
  });
}

if (
  !Number.isInteger(appointment_id) ||
  appointment_id < 0
) {
  errors.push({
    field: 'appointment_id',
    message: 'شناسه نوبت معتبر نیست.',
  });
}

if (!goals.includes(request_goal)) {
  errors.push({
    field: 'request_goal',
    message: 'هدف درخواست معتبر نیست.',
  });
}

if (!symptom_category) {
  errors.push({
    field: 'symptom_category',
    message: 'دسته کلی موضوع الزامی است.',
  });
}

if (!chief_complaint) {
  errors.push({
    field: 'chief_complaint',
    message: 'شرح اصلی درخواست یا مشکل الزامی است.',
  });
}

if (chief_complaint.length > 8000) {
  errors.push({
    field: 'chief_complaint',
    message: 'شرح مشکل بیش از حد طولانی است.',
  });
}

if (
  severity !== null &&
  (severity < 0 || severity > 10)
) {
  errors.push({
    field: 'severity',
    message: 'شدت باید عددی بین صفر و ده باشد.',
  });
}

if (!ageGroups.includes(age_group)) {
  errors.push({
    field: 'age_group',
    message: 'گروه سنی معتبر نیست.',
  });
}

if (!channels.includes(source_channel)) {
  errors.push({
    field: 'source_channel',
    message: 'کانال ورودی معتبر نیست.',
  });
}

if (consent_to_store_health_information !== true) {
  errors.push({
    field: 'consent_to_store_health_information',
    message: 'رضایت برای نگهداری اطلاعات سلامت الزامی است.',
  });
}

if (disclaimer_acknowledged !== true) {
  errors.push({
    field: 'disclaimer_acknowledged',
    message: 'تأیید محدودیت پاسخ‌گویی غیرتشخیصی الزامی است.',
  });
}

if (confirm_submission !== true) {
  errors.push({
    field: 'confirm_submission',
    message: 'ثبت درخواست باید به‌صورت صریح تأیید شود.',
  });
}

return [{
  json: {
    clinic_name,
    mobile,
    appointment_id,
    request_goal,
    symptom_category,
    chief_complaint,
    duration_text,
    severity,
    age_group,
    ...nullableBooleans,
    chronic_conditions,
    current_medications,
    source_channel,
    consent_to_contact,
    consent_to_store_health_information,
    disclaimer_acknowledged,
    confirm_submission,
    validation_status: errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];

return [{
  json: {
    success: false,
    result: 'invalid_request',
    message: 'اطلاعات شروع پرسش تخصصی ناقص یا نامعتبر است.',
    errors: $json.errors ?? [],
  },
}];
